static partial class FfmpegUi
{
    sealed record InteractionScript(int SourceWidth, int SourceHeight, int Left, int Top, int Width, int Height,
        string Report, string? HoldUntilFile = null, bool Clipboard = false, long FixtureWindow = 0, bool Input = true);

    sealed partial class DesktopWindow
    {
        readonly List<CursorUpdate> interactionCursors = new();
        readonly List<object> interactionInputTrace = new();
        async Task RunInteractionAsync(string path)
        {
            List<object> checks = new(); List<object> expected = new();
            var script = JsonSerializer.Deserialize<InteractionScript>(File.ReadAllText(path), AppConfiguration.JsonOptions) ?? throw new InvalidDataException("Missing interaction script.");
            void Check(bool passed, string name, object? evidence = null)
            {
                checks.Add(new { Name = name, Passed = passed, Evidence = evidence });
                if (!passed) throw new InvalidOperationException("Interaction regression: " + name);
            }
            async Task Until(Func<bool> condition)
            {
                var started = Stopwatch.GetTimestamp();
                while (!condition())
                {
                    if (Stopwatch.GetElapsedTime(started).TotalSeconds > 12) throw new TimeoutException("Interaction test condition not reached.");
                    await Task.Delay(20);
                }
            }
            try
            {
                preview.Input += input => interactionInputTrace.Add(new { Tick = Environment.TickCount64, input.Kind, input.ScanCode });
                Check(script.SourceWidth == session!.RemoteSourceWidth && script.SourceHeight == session.RemoteSourceHeight, "Fixture/source desktop dimensions agree");
                await Until(() => preview.VideoWidth == session.Configuration.Width && receivedFrames >= 3);
                foreach (var cap in new[] { .5m, 5m, 10m, 20m, 5m })
                {
                    if ((double)cap > bitrate.Maximum) continue;
                    var before = receivedFrames;
                    bitrate.Value = (double)cap;
                    await Until(() => !applying && pendingStatus?.AppliedLimitKbps == (int)(cap * 1000) && receivedFrames > before);
                    Check(Math.Abs(bitrate.Value - (double)cap) < .00001 && bitrateLabel.Text == $"码率上限 · {cap:0.0##} Mbps",
                        "Mbps slider, label and sender acknowledgement " + cap, new { Mbps = cap, SenderKbps = pendingStatus?.AppliedLimitKbps });
                }
                if (details.IsVisible) ToggleDetails();
                var bounds = Win32InputInjector.ReadPrimaryMonitor();
                foreach (var size in new[] { new Size(780, 520), new Size(1060, 640), new Size(900, 820) })
                {
                    Width = size.Width; Height = size.Height;
                    Position = new PixelPoint(Math.Max(0, bounds.Width - (int)(size.Width * RenderScaling) - 16), 16);
                    var dimensions = TransmissionGeometry.Dimensions(script.SourceWidth, script.SourceHeight, 1);
                    await Until(() => !applying && session.Configuration.TransmissionScale == 1 && preview.VideoWidth == dimensions.Width && preview.VideoHeight == dimensions.Height);
                    await Task.Delay(200);
                    Check(preview.VideoWidth == dimensions.Width && preview.VideoHeight == dimensions.Height, "Native decoded dimensions at resized window", new { size, dimensions.Width, dimensions.Height });
                    var watermarkOrigin = watermark.PointToScreen(new Point());
                    var clientOrigin = this.PointToScreen(new Point());
                    Check(watermark.VerifyPassThrough(preview.SourceWindow) && watermarkOrigin.X >= clientOrigin.X && watermarkOrigin.Y >= clientOrigin.Y &&
                        watermarkOrigin.X + watermark.ClientSize.Width * RenderScaling <= clientOrigin.X + ClientSize.Width * RenderScaling + 1 &&
                        watermarkOrigin.Y + watermark.ClientSize.Height * RenderScaling <= clientOrigin.Y + ClientSize.Height * RenderScaling + 1,
                        "Click-through, non-activating watermark stays inside resized preview", new { size, watermark.ClientSize });
                    if (!script.Input) continue;
                    await SetInputAsync(true);
                    for (var point = 0; point < 3; point++)
                    {
                        var targetX = script.Left + script.Width * (point + .5) / 3;
                        var targetY = script.Top + script.Height * .55;
                        GetClientRect(preview.SourceWindow, out var rectangle);
                        var x = (int)Math.Round(targetX / (script.SourceWidth - 1) * (rectangle.Right - 1));
                        var y = (int)Math.Round(targetY / (script.SourceHeight - 1) * (rectangle.Bottom - 1));
                        var lp = (nint)((y << 16) | (x & 0xFFFF));
                        var before = Interlocked.Read(ref inputSent);
                        SendMessage(preview.SourceWindow, 0x0200, 0, lp);
                        await Until(() => Interlocked.Read(ref inputSent) > before);
                        await Task.Delay(120);
                        SendMessage(preview.SourceWindow, 0x0201, 1, lp); await Task.Delay(70);
                        SendMessage(preview.SourceWindow, 0x0202, 0, lp); await Task.Delay(70);
                        if (script.FixtureWindow != 0 && remoteOptions?.Host == "127.0.0.1")
                        {
                            // A shared desktop moves focus away from the controller; isolate keyboard routing to our owned test fixture.
                            if (!SetForegroundWindow((nint)script.FixtureWindow)) throw new InvalidOperationException("Cannot focus local input fixture.");
                            await Task.Delay(60);
                        }
                        SendMessage(preview.SourceWindow, 0x0100, 0x58, (nint)(0x2D << 16 | 1));
                        SendMessage(preview.SourceWindow, 0x0101, 0x58, unchecked((nint)(long)(0xC0000001u | 0x2Du << 16)));
                        var screen = new InteractionPoint { X = x, Y = y }; ClientToScreen(preview.SourceWindow, ref screen);
                        SendMessage(preview.SourceWindow, 0x020A, (nuint)(120 << 16), (nint)((screen.Y << 16) | (screen.X & 0xFFFF)));
                        await Task.Delay(100);
                        expected.Add(new { Scale = 1, WindowWidth = size.Width, WindowHeight = size.Height, TargetX = targetX, TargetY = targetY,
                            PixelTolerance = Math.Ceiling(Math.Max(script.SourceWidth / (double)rectangle.Right, script.SourceHeight / (double)rectangle.Bottom)) + 2 });
                    }
                    await SetInputAsync(false);
                }
                var invalid = await session.ApplyAsync(config.InitialPreset, (int)Math.Round(bitrate.Value * 1000), .25);
                Check(!invalid.Success && session.Configuration.TransmissionScale == 1, "Invalid scale preserves native stream");
                if (script.Input)
                {
                await SetInputAsync(true);
                SendMessage(preview.SourceWindow, 0x0100, 0x10, (nint)(0x2A << 16 | 1));
                await Task.Delay(120);
                HandleLocalShortcut(0x11);
                await Until(() => inputClient?.Enabled == false);
                Check(inputEnabled.IsChecked == false, "Exit shortcut handler releases held input");
                Check(inputRejected == 0, "No injected input rejected", new { inputSent, inputRejected });
                Check(cursorClient is { Updates: > 0, Shapes: >= 3 }, "Cursor shape feedback is independent of video", new { cursorClient?.Updates, cursorClient?.Shapes });
                }
                else Check(inputSent == 0 && inputEnabled.IsChecked != true, "Automatic keyboard/mouse tests disabled; no input sent");
                if (script.Clipboard) { await SetClipboardAsync(true); updatingClipboard = true; clipboardEnabled.IsChecked = true; updatingClipboard = false; }
                Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(script.Report))!);
                File.WriteAllText(script.Report, JsonSerializer.Serialize(new { Passed = true, Checks = checks, ExpectedInput = expected, InputTrace = interactionInputTrace,
                    CursorShapes = interactionCursors.Where(update => update.Shape != null).Select(update => new { update.Id, update.Shape!.Width, update.Shape.Height, update.Shape.HotX, update.Shape.HotY }),
                    ClipboardEnabled = script.Clipboard, Note = "Input delivery is verified independently against the target window event log." }, AppConfiguration.JsonOptions));
                if (script.HoldUntilFile != null)
                {
                    var holdStart = Stopwatch.GetTimestamp();
                    while (!File.Exists(script.HoldUntilFile) && !stopping)
                    {
                        if (Stopwatch.GetElapsedTime(holdStart).TotalMinutes > 5) throw new TimeoutException("Interaction orchestration did not finish.");
                        await Task.Delay(100);
                    }
                }
            }
            catch (Exception error)
            {
                ReportError(error); regressionExitCode = 1;
                File.WriteAllText(script.Report, JsonSerializer.Serialize(new { Passed = false, Checks = checks, Error = error.ToString(), ExpectedInput = expected }, AppConfiguration.JsonOptions));
            }
            finally { if (!stopping) Close(); }
        }
        [StructLayout(LayoutKind.Sequential)] struct InteractionRect { public int Left, Top, Right, Bottom; }
        [StructLayout(LayoutKind.Sequential)] struct InteractionPoint { public int X, Y; }
        [DllImport("user32.dll")] static extern bool GetClientRect(nint hwnd, out InteractionRect rectangle);
        [DllImport("user32.dll")] static extern bool ClientToScreen(nint hwnd, ref InteractionPoint point);
        static nint SendMessage(nint hwnd, uint message, nuint wParam, nint lParam)
        {
            var previous = SetMessageExtraInfo(0);
            try { return NativeSendMessage(hwnd, message, wParam, lParam); }
            finally { SetMessageExtraInfo(previous); }
        }
        [DllImport("user32.dll", EntryPoint = "SendMessageW")] static extern nint NativeSendMessage(nint hwnd, uint message, nuint wParam, nint lParam);
        [DllImport("user32.dll")] static extern nint SetMessageExtraInfo(nint value);
        [DllImport("user32.dll")] static extern bool SetForegroundWindow(nint hwnd);
    }
}

// Source: FfmpegNetwork.cs
static class FrdNetwork
{
    public static IPAddress Canonical(IPAddress address) => address.IsIPv4MappedToIPv6 ? address.MapToIPv4() : address;
    public static bool SameEndpoint(EndPoint first, EndPoint second) => first is IPEndPoint a && second is IPEndPoint b &&
        a.Port == b.Port && Canonical(a.Address).Equals(Canonical(b.Address));
    public static int UdpOverhead(IPAddress address) => Canonical(address).AddressFamily == AddressFamily.InterNetworkV6 ? 48 : 28;
    public static IPAddress Any(AddressFamily family) => family == AddressFamily.InterNetworkV6 ? IPAddress.IPv6Any : IPAddress.Any;
    public static IPAddress[] ListenAddresses(string value) => value.Equals("localhost", StringComparison.OrdinalIgnoreCase)
        ? [IPAddress.Loopback, IPAddress.IPv6Loopback] : [Canonical(IPAddress.Parse(value))];
    public static async Task<TcpClient> ConnectAsync(string host, int port, CancellationToken token)
    {
        var addresses = IPAddress.TryParse(host, out var literal) ? [literal] : await Dns.GetHostAddressesAsync(host, token);
        Exception? failure = null;
        foreach (var address in addresses.Select(Canonical).Distinct())
        {
            var client = new TcpClient(address.AddressFamily) { NoDelay = true };
            try { await client.ConnectAsync(address, port, token); return client; }
            catch (SocketException error)
            {
                client.Dispose(); failure = error;
                Console.Error.WriteLine($"[connect] {address}:{port}: {error.Message}");
            }
            catch { client.Dispose(); throw; }
        }
        throw new IOException($"Cannot connect to {host}:{port}.", failure);
    }
}

// Source: FfmpegPresentation.cs
public sealed class ConfirmedVideoView : NativeControlHost
{
    readonly object gate = new();
    readonly AutoResetEvent changed = new(false);
    DecodedPixels? pending;
    NativeInputSource? inputSource;
    Thread? renderThread;
    nint sourceWindow;
    bool stopped, inputEnabled;
    int sourceWidth = 1280, sourceHeight = 720;

    public event Action<long, long>? Presented;
    public event Action<Exception>? Failed;
    public event Action<RemoteInputEvent>? Input;
    public event Action? InputExitRequested;
    public event Action<int>? LocalShortcutRequested;
    public nint SourceWindow => sourceWindow;
    public int VideoWidth => Volatile.Read(ref sourceWidth);
    public int VideoHeight => Volatile.Read(ref sourceHeight);
    public void SetRemoteCursor(CursorUpdate update) => inputSource?.SetRemoteCursor(update);

    public void SetInputEnabled(bool enabled)
    {
        if (!Dispatcher.UIThread.CheckAccess()) throw new InvalidOperationException("Input mode must change on the UI thread.");
        inputEnabled = enabled;
        inputSource?.SetEnabled(enabled);
    }

    public ConfirmedVideoView()
    {
        HorizontalAlignment = HorizontalAlignment.Center;
        VerticalAlignment = VerticalAlignment.Center;
    }

    public void Submit(DecodedPixels pixels)
    {
        if (pixels.Width is <= 0 or > 8192 || pixels.Height is <= 0 or > 8192 ||
            pixels.Bgra.Length != checked(pixels.Width * pixels.Height * 4))
            throw new ArgumentException("Invalid tightly packed BGRA image.", nameof(pixels));
        lock (gate)
        {
            if (stopped) return;
            // Decoder output owns a fresh immutable array; replacement only discards unrendered output.
            pending = pixels;
            changed.Set();
        }
    }

    protected override Size MeasureOverride(Size availableSize)
    {
        var width = Volatile.Read(ref sourceWidth);
        var height = Volatile.Read(ref sourceHeight);
        var scale = Math.Min(availableSize.Width / width, availableSize.Height / height);
        if (!double.IsFinite(scale)) scale = 1;
        return new(width * Math.Max(0, scale), height * Math.Max(0, scale));
    }

    protected override IPlatformHandle CreateNativeControlCore(IPlatformHandle parent)
    {
        var hwnd = CreateWindowEx(0, "STATIC", "", 0x40000000 | 0x10000000 | 0x04000000,
            0, 0, sourceWidth, sourceHeight, parent.Handle, 0, 0, 0);
        if (hwnd == 0) throw new Win32Exception(Marshal.GetLastWin32Error(), "Cannot create D3D11 presentation window.");
        sourceWindow = hwnd;
        inputSource = new(hwnd);
        inputSource.Input += value => Input?.Invoke(value);
        inputSource.ExitRequested += () => { inputEnabled = false; InputExitRequested?.Invoke(); };
        inputSource.LocalShortcutRequested += key => LocalShortcutRequested?.Invoke(key);
        inputSource.Failed += Report;
        inputSource.SetEnabled(inputEnabled);
        lock (gate)
        {
            if (!stopped)
            {
                renderThread = new(() => Render(hwnd)) { IsBackground = true, Name = "FRD confirmed GPU presentation" };
                renderThread.Start();
            }
        }
        return new PlatformHandle(hwnd, "HWND");
    }

    protected override void DestroyNativeControlCore(IPlatformHandle control)
    {
        inputSource?.Dispose();
        inputSource = null;
        Stop();
        if (control.Handle != 0 && !DestroyWindow(control.Handle))
            Report(new Win32Exception(Marshal.GetLastWin32Error(), "Cannot destroy D3D11 presentation window."));
        sourceWindow = 0;
    }

    public void Stop()
    {
        Thread? thread;
        lock (gate)
        {
            if (stopped) return;
            stopped = true;
            pending = null;
            thread = renderThread;
            changed.Set();
        }
        if (thread is not null && thread != Thread.CurrentThread && !thread.Join(2000))
        {
            Report(new TimeoutException("D3D11 presentation thread did not stop within 2 seconds."));
            return;
        }
        changed.Dispose();
    }

    unsafe void Render(nint hwnd)
    {
        try
        {
            D3D11CreateDevice(null, DriverType.Hardware, DeviceCreationFlags.BgraSupport,
                [FeatureLevel.Level_11_1, FeatureLevel.Level_11_0], out ID3D11Device device, out ID3D11DeviceContext context).CheckError();
            using (device)
            using (context)
            using (var factory = CreateDXGIFactory2<IDXGIFactory2>(false))
            using (var completion = device.CreateQuery(new QueryDescription(QueryType.Event)))
            {
                using (var dxgiDevice = device.QueryInterface<IDXGIDevice1>()) dxgiDevice.MaximumFrameLatency = 1;
                factory.MakeWindowAssociation(hwnd, WindowAssociationFlags.IgnoreAltEnter).CheckError();
                IDXGISwapChain1? swap = null;
                byte[]? lastPixels = null;
                var width = 0;
                var height = 0;
                try
                {
                    while (true)
                    {
                        DecodedPixels? pixels;
                        lock (gate)
                        {
                            if (stopped) return;
                            pixels = pending;
                            pending = null;
                        }
                        if (pixels is null) { changed.WaitOne(250); continue; }
                        if (pixels.Width == width && pixels.Height == height && lastPixels is not null &&
                            pixels.Bgra.AsSpan().SequenceEqual(lastPixels)) continue;
                        if (pixels.Width != width || pixels.Height != height)
                        {
                            swap?.Dispose();
                            swap = factory.CreateSwapChainForHwnd(device, hwnd, new SwapChainDescription1
                            {
                                Width = (uint)pixels.Width, Height = (uint)pixels.Height,
                                Format = Format.B8G8R8A8_UNorm, BufferCount = 2,
                                BufferUsage = Usage.RenderTargetOutput, SampleDescription = new(1, 0),
                                SwapEffect = SwapEffect.FlipDiscard, Scaling = Scaling.Stretch, AlphaMode = AlphaMode.Ignore
                            });
                            width = pixels.Width;
                            height = pixels.Height;
                            Volatile.Write(ref sourceWidth, width);
                            Volatile.Write(ref sourceHeight, height);
                            Dispatcher.UIThread.Post(InvalidateMeasure);
                        }
                        using (var backBuffer = swap!.GetBuffer<ID3D11Texture2D>(0))
                            fixed (byte* source = pixels.Bgra)
                                context.UpdateSubresource(backBuffer, 0, null, (nint)source, (uint)(width * 4), 0);
                        var presentResult = swap!.Present(0, PresentFlags.None);
                        presentResult.CheckError();
                        if (presentResult.Code != 0) continue;
                        // The event confirms GPU commands after Present; it does not measure physical scan-out.
                        context.End(completion);
                        context.Flush();
                        uint done = 0;
                        var deadline = Stopwatch.GetTimestamp() + Stopwatch.Frequency;
                        while (true)
                        {
                            var result = context.GetData(completion, (nint)(&done), sizeof(uint), AsyncGetDataFlags.DoNotFlush);
                            result.CheckError();
                            if (result.Code == 0 && done != 0) break;
                            lock (gate) { if (stopped) return; }
                            if (Stopwatch.GetTimestamp() >= deadline) throw new TimeoutException("GPU presentation confirmation exceeded 1 second.");
                            Thread.Yield();
                        }
                        var completed = Stopwatch.GetTimestamp();
                        lastPixels = pixels.Bgra;
                        Presented?.Invoke(pixels.Pts, completed);
                    }
                }
                finally { swap?.Dispose(); }
            }
        }
        catch (Exception error) { Report(error); }
    }

    void Report(Exception error)
    {
        Console.Error.WriteLine($"[GPU presentation] {error}");
        try { Failed?.Invoke(error); }
        catch (Exception callbackError) { Console.Error.WriteLine($"[GPU presentation error callback] {callbackError}"); }
    }

    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    static extern nint CreateWindowEx(uint extendedStyle, string className, string name, uint style,
        int x, int y, int width, int height, nint parent, nint menu, nint instance, nint parameter);
    [DllImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    static extern bool DestroyWindow(nint hwnd);
}

