                    }), inputStop.Token);
                if (stopping) return;
                started = true; presets.IsEnabled = true; UpdateBitrateAvailability();
                foreach (var button in fpsButtons) button.IsEnabled = true;
                inputEnabled.IsEnabled = packetDiagnostics.IsEnabled = true;
                clipboardEnabled.IsEnabled = session.IsRemote;
                operation.Text = $"已连接：{config.InitialPreset} / {(HasSelectedBitrateCap() ? $"{config.InitialBitrateKbps / 1000d:0.###} Mbps" : "无损不限码率")} / 原始分辨率 {config.Width}×{config.Height}";
                if (!session.IsRemote) clipboardMessage.Text = "localhost 共用剪贴板；双机连接后可开启";
                if (InteractionScriptPath != null)
                {
                    await VerifyOverlayAsync();
                    await RunInteractionAsync(InteractionScriptPath); return;
                }
                if (autoCloseSeconds > 0)
                {
                    await VerifyOverlayAsync();
                    if (stopping) return;
                    autoClose.Interval = TimeSpan.FromSeconds(autoCloseSeconds); autoClose.Start();
                }
            }
            catch (OperationCanceledException) when (stopping) { Console.Error.WriteLine("Window startup cancelled during shutdown."); }
            catch (Exception ex)
            {
                ReportError(ex);
                regressionExitCode = 1;
                Close();
            }
        }

        void ScheduleApply()
        {
            if (!started || stopping) return;
            debounce.Stop(); debounce.Start();
        }

        async Task StartInputAsync()
        {
            if (session?.IsRemote == true)
            {
                if (inputWorker != null) await inputWorker;
                inputClient = await session.ConnectRemoteInputAsync(inputStop.Token);
                inputChannelStop?.Dispose();
                inputChannelStop = CancellationTokenSource.CreateLinkedTokenSource(inputStop.Token);
                var connected = inputClient;
                var channelToken = inputChannelStop.Token;
                inputWorker = Task.Run(() => SendInputLoopAsync(connected, channelToken)); return;
            }
            inputInjector = new();
            inputInjector.RegisterControllerWindow(TryGetPlatformHandle()?.Handle ?? 0);
            inputInjector.RegisterControllerWindow(overlay.TryGetPlatformHandle()?.Handle ?? 0);
            inputInjector.RegisterControllerWindow(watermark.TryGetPlatformHandle()?.Handle ?? 0);
            inputInjector.RegisterControllerWindow(preview.SourceWindow);
            inputServer = new(inputInjector);
            inputServer.Failed += ex => Dispatcher.UIThread.Post(() => ReportError(ex));
            var client = await RemoteInputClient.ConnectAsync(inputServer.Endpoint, inputStop.Token);
            if (stopping || inputStop.IsCancellationRequested) { client.Dispose(); return; }
            inputClient = client;
            inputChannelStop = CancellationTokenSource.CreateLinkedTokenSource(inputStop.Token);
            var localToken = inputChannelStop.Token;
            inputWorker = Task.Run(() => SendInputLoopAsync(client, localToken));
        }

        async Task SetClipboardAsync(bool enabled)
        {
            await clipboardTransition.WaitAsync();
            try
            {
                clipboardEnabled.IsEnabled = false;
                if (clipboardSync != null) { await clipboardSync.DisposeAsync(); clipboardSync = null; }
                if (enabled)
                {
                    clipboardSync = await session!.ConnectRemoteClipboardAsync(new WindowsClipboard(TryGetPlatformHandle()?.Handle ?? 0), inputStop.Token);
                    clipboardSync.Status += status => Dispatcher.UIThread.Post(() =>
                    {
                        clipboardMessage.Text = status.Message;
                        if (!status.Connected && !stopping) clipboardEnabled.IsChecked = false;
                    });
                }
                clipboardMessage.Text = enabled ? "已开启；同步两端新复制的内容" : "已关闭剪贴板同步";
            }
            finally { clipboardEnabled.IsEnabled = !stopping && session?.IsRemote == true; clipboardTransition.Release(); }
        }

        async void ChangeDiagnostics()
        {
            if (updatingDiagnostics || changingDiagnostics || !started || stopping || session == null) return;
            changingDiagnostics = true; packetDiagnostics.IsEnabled = false;
            try
            {
                var enabled = packetDiagnostics.IsChecked == true;
                var result = await session.SetPacketDiagnosticsAsync(enabled);
                if (!result.Success) throw new InvalidOperationException(result.Message);
                operation.Text = enabled ? "独立诊断 UDP 包已开启，开销计入实际流量；滑条只限制编码码率。" : "诊断包已关闭；本机分层计时仍然可用。";
            }
            catch (Exception ex)
            {
                updatingDiagnostics = true;
                lock (receiveGate) packetDiagnostics.IsChecked = pendingStatus?.PacketDiagnosticsEnabled == true;
                updatingDiagnostics = false; ReportError(ex);
            }
            finally { changingDiagnostics = false; packetDiagnostics.IsEnabled = started && !stopping; }
        }

        async void ChangeInputToggle()
        {
            if (updatingInput || stopping) return;
            try { await SetInputAsync(inputEnabled.IsChecked == true); }
            catch (Exception ex) { ReportError(ex); }
        }

        async Task SetInputAsync(bool enabled, CancellationToken token = default)
        {
            if (!enabled) { preview.SetInputEnabled(false); lock (inputGate) inputQueue.Clear(); }
            await inputTransition.WaitAsync();
            inputEnabled.IsEnabled = false;
            try
            {
                enabled &= !stopping;
                if (enabled && inputClient == null) await StartInputAsync();
                if (inputClient == null) throw new InvalidOperationException("输入通道尚未连接");
                var result = await inputClient.SetEnabledAsync(enabled, token);
                if (!result.Accepted) throw new InvalidOperationException(result.Message);
                if (enabled && stopping) { await inputClient.SetEnabledAsync(false); enabled = false; }
                preview.SetInputEnabled(enabled);
                updatingInput = true; inputEnabled.IsChecked = enabled; updatingInput = false;
                operation.Text = enabled ? "键鼠转发已启用，按 Ctrl+Alt 退出并释放按键。"
                    : "键鼠转发已关闭，按键已释放。";
            }
            catch
            {
                preview.SetInputEnabled(false);
                updatingInput = true; inputEnabled.IsChecked = false; updatingInput = false;
                throw;
            }
            finally { inputEnabled.IsEnabled = started && !stopping; inputTransition.Release(); }
        }

        void QueueInput(RemoteInputEvent input)
        {
            if (stopping || inputClient?.Enabled != true) return;
            var source = capture?.Statistics;
            var mapped = session?.IsRemote == true ? InputCoordinates.MapFromVideo(input, preview.VideoWidth, preview.VideoHeight, session.RemoteSourceWidth, session.RemoteSourceHeight) :
                source == null ? input : InputCoordinates.MapFromVideo(input, preview.VideoWidth, preview.VideoHeight, source.SourceWidth, source.SourceHeight);
            if (mapped == null) return;
            lock (inputGate)
            {
                if (mapped.Kind == RemoteInputKind.MouseMove && inputQueue.Last?.Value.Kind == RemoteInputKind.MouseMove)
                { inputQueue.Last.Value = mapped; coalescedMoves++; }
                else if (inputQueue.Count < 512) inputQueue.AddLast(mapped);
                else
                {
                    preview.SetInputEnabled(false);
                    var overflow = new InvalidOperationException("键鼠转发积压，已停止输入并释放按键；未继续累积事件。");
                    if (session?.IsRemote == true) HandleInputFailure(inputClient!, overflow);
                    else ReportError(overflow);
                    return;
                }
                if (inputReady.CurrentCount == 0) inputReady.Release();
            }
        }

        async Task SendInputLoopAsync(RemoteInputClient connected, CancellationToken channelToken)
        {
            using var sending = CancellationTokenSource.CreateLinkedTokenSource(channelToken);
            List<Task> confirmations = new();
            Exception? failure = null;
            try
            {
                while (!sending.IsCancellationRequested)
                {
                    await inputReady.WaitAsync(sending.Token);
                    while (true)
                    {
                        RemoteInputEvent? next;
                        lock (inputGate) { next = inputQueue.First?.Value; if (next != null) inputQueue.RemoveFirst(); }
                        if (next == null) break;
                        // Preserve wire order, but let the next input leave before this event's remote confirmation.
                        var confirmation = await connected.QueueAsync(next, sending.Token);
                        confirmations.RemoveAll(task => task.IsCompleted);
                        confirmations.Add(ObserveAsync(confirmation));
                    }
                }
            }
            catch (OperationCanceledException) when (sending.IsCancellationRequested) { Console.Error.WriteLine("Input send queue stopped."); }
            catch (Exception error) { Fail(error); }
            finally { await Task.WhenAll(confirmations); }

            async Task ObserveAsync(Task<RemoteInputResult> confirmation)
            {
                try
                {
                    var result = await confirmation;
                    if (result.Accepted) Interlocked.Increment(ref inputSent);
                    else
                    {
                        Interlocked.Increment(ref inputRejected);
                        lock (inputGate)
                        {
                            if (result.Message == lastInputMessage) return;
                            lastInputMessage = result.Message;
                        }
                        Console.Error.WriteLine("[input rejected] " + result.Message);
                        Dispatcher.UIThread.Post(() => operation.Text = "输入未注入：" + result.Message);
                    }
                }
                catch (OperationCanceledException) when (inputStop.IsCancellationRequested) { Console.Error.WriteLine("Input confirmation stopped."); }
                catch (Exception error) { Fail(error); }
            }

            void Fail(Exception error)
            {
                if (Interlocked.CompareExchange(ref failure, error, null) != null) return;
                Console.Error.WriteLine(error);
                connected.Dispose();
                sending.Cancel();
                Dispatcher.UIThread.Post(() => HandleInputFailure(connected, error));
            }
        }

        void HandleInputFailure(RemoteInputClient connected, Exception error)
        {
            if (stopping || !ReferenceEquals(inputClient, connected)) return;
            SessionTrace.Error("input-auxiliary", error);
            inputChannelStop?.Cancel(); connected.Dispose(); inputClient = null;
            preview.SetInputEnabled(false);
            lock (inputGate) inputQueue.Clear();
            updatingInput = true; inputEnabled.IsChecked = false; updatingInput = false;
            operation.Text = "键鼠通道已中断；视频仍在运行。重新勾选“键鼠”可建立新的输入通道。";
        }

        void UpdateFpsButtons()
        {
            foreach (var button in fpsButtons)
                button.Opacity = (int)button.Tag! == selectedFps ? 1 : .55;
        }

        async Task StopInputAsync()
        {
            preview.SetInputEnabled(false);
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(1));
            try { if (inputClient != null) await SetInputAsync(false, timeout.Token); }
            finally
            {
                inputStop.Cancel(); inputChannelStop?.Cancel(); inputClient?.Dispose();
                if (inputWorker != null) await inputWorker;
                inputChannelStop?.Dispose();
                inputServer?.Dispose();
                inputInjector?.Dispose();
            }
        }

        async void ApplySelection()
        {
            debounce.Stop();
            if (!started || stopping || session == null) return;
            if (applying) { applyAgain = true; return; }
            if (presets.SelectedItem is not ComboBoxItem { Tag: string presetId }) return;
            applying = true;
            var limit = (int)Math.Round(bitrate.Value * 1000);
            var rateText = HasSelectedBitrateCap() ? $"{limit / 1000d:0.###} Mbps" : "无损不限码率";
            operation.Text = $"正在请求被控端应用 {presetId} / {rateText} / {selectedFps} FPS…";
            try
            {
                var result = await session.ApplyAsync(presetId, limit, framesPerSecond: selectedFps);
                config = session.Configuration;
                if (result.Success) successfulChanges++;
                if (!result.Success) { selectedFps = config.FramesPerSecond; UpdateFpsButtons(); }
                operation.Text = result.Success ? $"已应用：{presetId} / {rateText} / {config.FramesPerSecond} FPS / {config.Width}×{config.Height}（会话 {result.Generation}）" : $"切换未生效，保留原会话：{result.Message}";
                if (!result.Success) Console.Error.WriteLine($"[UI control] {result.Message}");
            }
            catch (Exception ex) { ReportError(ex); }
            finally
            {
                applying = false;
                if (applyAgain && !stopping) { applyAgain = false; debounce.Start(); }
            }
        }

        void RefreshStatus()
        {
            if (!stopping && session?.IsRemote == true && inputClient is { Failure: { } inputError } failedInput)
                HandleInputFailure(failedInput, inputError);
            if (disconnected)
            {
                summary.Text = "原会话已断开 · 等待手动建立新会话";
                metrics.Text = "查看控制栏中的断连原因；原 TCP 连接不会自动重新握手。";
                return;
            }
            SessionStatus? status;
            lock (receiveGate) status = pendingStatus;
            var remoteWait = session?.RemoteStatusWaitSeconds ?? 0;
            if (status is { } currentStatus)
            {
                string Mean(double value) => currentStatus.HasRenderTiming && currentStatus.HasRecentRenderTiming ? $"{value:F2}" : "—";
                var latency = currentStatus.HasRenderTiming ? $"最近 {currentStatus.CaptureToRenderMs:F1} / 近 1 秒平均 {Mean(currentStatus.MeanCaptureToRenderMs)} ms（{currentStatus.RenderTimingSamples} 帧）" : "等待首次 GPU 确认";
                var cap = currentStatus.AppliedLimitKbps > 0 ? $"{currentStatus.AppliedLimitKbps / 1000d:0.###} Mbps" : "无损不限码率";
                summary.Text = $"{currentStatus.ActivePreset} · {cap} · {currentStatus.RenderedFps:F1} FPS · 近 1 秒 {Mean(currentStatus.MeanCaptureToRenderMs)} ms";
                metrics.Text = $"发送 {currentStatus.SentMbps:F3} / 接收 {currentStatus.ReceivedMbps:F3} Mbps  |  带宽估计 {currentStatus.EstimatedMbps:F3} Mbps（参考）\n诊断包：{(currentStatus.PacketDiagnosticsEnabled ? "开" : "关")}，开销 {currentStatus.DiagnosticMbps * 1000:F2} kbps（已计入流量）\n捕获 → GPU 完成：{latency}  |  绘制 {currentStatus.RenderedFps:F1} / 解码 {currentStatus.DecodedFps:F1} FPS\n网络延迟趋势 {currentStatus.DelayTrendMs:+0.00;-0.00;0.00} ms  |  丢包 {currentStatus.LossRate:P1}  |  {currentStatus.Message}";
                if (!changingDiagnostics) { updatingDiagnostics = true; packetDiagnostics.IsChecked = currentStatus.PacketDiagnosticsEnabled; updatingDiagnostics = false; }
                metrics.Text += "\n" + currentStatus.TimingDescription;
                metrics.Text += status.SimulatedCapacityMbps > 0
                    ? $" · 专项链路模拟 {status.SimulatedCapacityMbps:0.##} Mbps"
                    : " · UDP 即时发送，滑条仅限制编码码率";
                if (remoteWait >= 3)
                {
                    summary.Text = $"网络路径暂停 {remoteWait:F0} 秒 · 等待原会话恢复";
                    metrics.Text = $"控制连接仍未被明确关闭；已等待 {remoteWait:F1} 秒。画面与统计可能暂时停留在上一状态。\n" + metrics.Text;
                }
                timings[0].Text = $"捕获  {currentStatus.CaptureMs:F2} / {Mean(currentStatus.MeanCaptureMs)}";
                timings[1].Text = $"编码  {currentStatus.EncodeMs:F2} / {Mean(currentStatus.MeanEncodeMs)}";
                var transfer = currentStatus.TransferDetails;
                timings[2].Text = $"传输  {currentStatus.TransferMs:F2} / {Mean(currentStatus.MeanTransferMs)}" +
                    (transfer == null ? "" : $"\n最近 {transfer.PayloadBytes:N0} B / {transfer.Packets} 包\n发送侧 {transfer.SenderMs:F2}（计划等 {transfer.PlannedWaitMs:F2} / 额外等 {transfer.WakeupOverrunMs:F2}）\n末包发送→收齐 {transfer.LastSendToReassemblyMs:F2} / 接收排队 {transfer.ReceiveQueueMs:F2}");
                timings[3].Text = $"解码  {currentStatus.DecodeMs:F2} / {Mean(currentStatus.MeanDecodeMs)}";
                timings[4].Text = $"渲染  {currentStatus.RenderMs:F2} / {Mean(currentStatus.MeanRenderMs)}";
                timings[5].Text = $"合计  {currentStatus.CaptureToRenderMs:F2} / {Mean(currentStatus.MeanCaptureToRenderMs)}";
                if (session?.IsRemote == true && !currentStatus.HasRenderTiming)
                    foreach (var timing in timings) timing.Text = (timing.Text ?? "").Split(' ')[0] + "  — / —";
                var stages = capture?.Statistics;
                captureDetails.Text = session?.IsRemote == true ? $"被控桌面 {session.RemoteSourceWidth}×{session.RemoteSourceHeight} → {session.Configuration.Width}×{session.Configuration.Height}；本机仅接收、解码、渲染" : stages == null ? $"捕获后端：{capture?.Backend ?? "启动中"}" :
                    $"DXGI 捕获最近一次（ms）：取帧 {stages.AcquireMs:F2} / 缩放提交 {stages.GpuScaleSubmitMs:F2} / 回读等待 {stages.MapWaitAndReadbackMs:F2} / 像素复制 {stages.CpuRowCopyMs:F2}";
            }
        }

        async void Shutdown(object? sender, WindowClosingEventArgs args)
        {
            if (allowClose) return;
            args.Cancel = true;
            if (stopping) return;
            stopping = true; debounce.Stop(); autoClose.Stop();
            SessionTrace.Event("window", disconnected ? "closing-after-disconnect" : scheduledClose ? "closing-scheduled" : "closing-by-user-or-test");
            presets.IsEnabled = bitrate.IsEnabled = packetDiagnostics.IsEnabled = inputEnabled.IsEnabled = clipboardEnabled.IsEnabled = false; operation.Text = "正在关闭捕获、FFmpeg 与 UDP…";
            try { await SetClipboardAsync(false); } catch (Exception ex) { ReportError(ex); }
            try { if (cursorClient != null) await cursorClient.DisposeAsync(); } catch (Exception ex) { ReportError(ex); }
            try { await StopInputAsync(); } catch (Exception ex) { ReportError(ex); }
            try { if (session != null) await session.StopAsync(); }
            catch (Exception ex) { ReportError(ex); }
            finally
            {
                refresh.Stop();
                preview.Stop();
                try { session?.Dispose(); } catch (Exception ex) { ReportError(ex); }
                captureBackend = capture?.Backend; captureStatistics = capture?.Statistics;
                try { capture?.Dispose(); } catch (Exception ex) { ReportError(ex); }
                WriteReport(); allowClose = true;
                Dispatcher.UIThread.Post(() => { watermark.Close(); overlay.Close(); Close(); });
            }
        }

        void ReportError(Exception ex)
        {
            SessionTrace.Error("controller-window", ex);
            Console.Error.WriteLine(ex); errors.Add(ex.ToString()); operation.Text = "错误：" + ex.Message;
            regressionExitCode = 1;
            if (stopping) return;
            if (remoteOptions == null) { Dispatcher.UIThread.Post(Close); return; }
            disconnected = true;
            preview.SetInputEnabled(false);
            presets.IsEnabled = bitrate.IsEnabled = packetDiagnostics.IsEnabled = inputEnabled.IsEnabled = clipboardEnabled.IsEnabled = false;
            foreach (var button in fpsButtons) button.IsEnabled = false;
            reconnect.IsVisible = true;
            operation.Text = $"原连接已中断：{ex.Message}；点击“重新建立会话”将创建新连接。";
            SessionTrace.Event("window", "disconnected-awaiting-user");
        }

        void LaunchNewSession()
        {
            if (remoteOptions == null) return;
            try
            {
                var executable = Path.Combine(AppContext.BaseDirectory, "FRD.exe");
                var start = new ProcessStartInfo(executable) { UseShellExecute = false };
                foreach (var argument in new[] { "--connect", remoteOptions.Host, "--port", remoteOptions.Port.ToString(),
                    "--token", remoteOptions.Token }) start.ArgumentList.Add(argument);
                using var launched = Process.Start(start) ?? throw new InvalidOperationException("未能启动新的主控进程。");
                SessionTrace.Event("window", "user-requested-new-process-and-session");
            }
            catch (Exception error)
            {
                SessionTrace.Error("manual-new-session", error);
                Console.Error.WriteLine(error);
            }
        }

        void WriteReport()
        {
            if (reportPath == null) return;
            try
            {
                var path = Path.GetFullPath(reportPath); Directory.CreateDirectory(Path.GetDirectoryName(path)!);
                SessionStatus? status; long frames;
                lock (receiveGate) status = pendingStatus;
                frames = Interlocked.Read(ref receivedFrames);
                var presented = Interlocked.Read(ref shownFrames);
                var stageSum = status == null ? 0 : status.CaptureMs + status.EncodeMs + status.TransferMs + status.DecodeMs + status.RenderMs;
                var meanStageSum = status == null ? 0 : status.MeanCaptureMs + status.MeanEncodeMs + status.MeanTransferMs + status.MeanDecodeMs + status.MeanRenderMs;
                var timingPassed = status?.HasRenderTiming == true && Math.Abs(stageSum - status.CaptureToRenderMs) < .00001 && Math.Abs(meanStageSum - status.MeanCaptureToRenderMs) < .00001;
                var transport = status?.TransferDetails;
                var transportPassed = transport != null && Math.Abs(transport.SenderMs + transport.LastSendToReassemblyMs + transport.ReceiveQueueMs - status!.TransferMs) < .00001;
                var dxgi = session?.IsRemote == true || captureBackend?.StartsWith("DXGI", StringComparison.Ordinal) == true;
                var finalOverlayBounds = CheckOverlayBounds(details.IsVisible);
                var passed = started && frames > 0 && presented > 0 && timingPassed && transportPassed && dxgi && overlayPassed && finalOverlayBounds.Passed && errors.Count == 0;
                File.WriteAllText(path, JsonSerializer.Serialize(new
                {
                    Passed = passed, Technology = "Avalonia", RealDesktopCapture = true, RemoteController = session?.IsRemote == true, CanResize, Started = started,
                    DurationSeconds = (DateTime.UtcNow - startedUtc).TotalSeconds,
                    ReceivedFrames = frames, GpuConfirmedFrames = presented, SuccessfulManualChanges = successfulChanges,
                    ManualLimitMinimumMbps = bitrate.Minimum, ManualLimitMaximumMbps = bitrate.Maximum,
                    ManualLimitMinimumKbps = bitrate.Minimum * 1000, ManualLimitMaximumKbps = bitrate.Maximum * 1000,
                    Overlay = new { OwnedByPreview = overlay.Owner == this, Visible = overlay.IsVisible, Expanded = details.IsVisible, overlay.Width, Height = overlay.ClientSize.Height, Position = overlay.Position.ToString() },
                    OverlayRegression = overlayCheck, FinalOverlayBounds = finalOverlayBounds,
                    TimingRegression = new { Passed = timingPassed, TransferBreakdownPassed = transportPassed, LatestStageSumMs = stageSum, LatestTotalMs = status?.CaptureToRenderMs, MeanStageSumMs = meanStageSum, MeanTotalMs = status?.MeanCaptureToRenderMs },
                    Input = new { RequiresManualEnable = true, LocalWheelAndKeyboardOnly = false, SystemInputInjection = true, SentEvents = Interlocked.Read(ref inputSent), RejectedEvents = Interlocked.Read(ref inputRejected), CoalescedMouseMoves = coalescedMoves, PendingEvents = inputQueue.Count },
                    Status = status, Session = session?.GetReport(), Errors = errors,
                    Capture = captureBackend, CaptureStatistics = captureStatistics,
                    Render = "D3D11 upload → Present(0) → event query GPU completion; physical scan-out is not timed"
                }, new JsonSerializerOptions { WriteIndented = true }));
                if (autoCloseSeconds > 0 && !passed) regressionExitCode = 1;
            }
            catch (Exception ex) { Console.Error.WriteLine($"[UI report] {ex}"); regressionExitCode = 1; }
        }

        [DllImport("user32.dll", SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        static extern bool SetWindowDisplayAffinity(nint window, uint affinity);
        [DllImport("user32.dll")] static extern nint GetWindow(nint window, uint relation);
    }

    sealed class PresentationTestWindow : Window
    {
        readonly ConfirmedVideoView view = new();
        readonly TextBlock progress = new() { Text = "GPU 呈现回归：A → 重复 A → 单像素变化 B → 重复 B", Margin = new Thickness(8) };
        readonly AppConfiguration config;
        readonly string reportPath;
        readonly CancellationTokenSource cancellation = new();
        readonly object gate = new();
        readonly List<long> presentedIds = new();
        readonly List<string> errors = new();
        readonly List<object> assertions = new();

        public PresentationTestWindow(AppConfiguration config, string reportPath)
        {
            this.config = config; this.reportPath = reportPath;
            Title = "FRD — GPU 呈现回归（完成后自动关闭）";
            Width = 960; Height = 640; CanResize = true; WindowStartupLocation = WindowStartupLocation.CenterScreen;
            var layout = new Grid { RowDefinitions = new("*,Auto"), Margin = new Thickness(8) };
            layout.Children.Add(new Border { Background = Brushes.Black, Child = view });
            Grid.SetRow(progress, 1); layout.Children.Add(progress); Content = layout;
            view.Presented += (id, _) => { lock (gate) presentedIds.Add(id); };
            view.Failed += ex => { Console.Error.WriteLine(ex); lock (gate) errors.Add(ex.ToString()); };
            Opened += RunTest;
            Closing += (_, _) => cancellation.Cancel();
            Closed += (_, _) => view.Stop();
        }

        int PresentedCount { get { lock (gate) return presentedIds.Count; } }

        async void RunTest(object? sender, EventArgs args)
        {
            var elapsed = System.Diagnostics.Stopwatch.StartNew();
            try
            {
                await Task.Delay(80, cancellation.Token);
                CheckAspect("Initial window");
                var a = new byte[checked(config.Width * config.Height * 4)];
                for (var i = 0; i < a.Length; i += 4) { a[i] = 72; a[i + 1] = 48; a[i + 2] = 32; a[i + 3] = 255; }
                view.Submit(new(a, config.Width, config.Height, 100));
                await AwaitCount(1); CheckCount("A", 1);
                view.Submit(new((byte[])a.Clone(), config.Width, config.Height, 101));
                await Task.Delay(200, cancellation.Token); CheckCount("Repeated A", 1);
                var b = (byte[])a.Clone(); b[((config.Height / 2) * config.Width + config.Width / 2) * 4 + 2] = 255;
                view.Submit(new(b, config.Width, config.Height, 102));
                await AwaitCount(2); CheckCount("One pixel B", 2);
                view.Submit(new((byte[])b.Clone(), config.Width, config.Height, 103));
                await Task.Delay(200, cancellation.Token); CheckCount("Repeated B", 2);
                Width = 1200; Height = 800;
                await Task.Delay(100, cancellation.Token); CheckAspect("Resized window");
            }
            catch (Exception ex) { Console.Error.WriteLine(ex); lock (gate) errors.Add(ex.ToString()); }
            finally
            {
                view.Stop();
                try
                {
                    var passed = errors.Count == 0 && assertions.Count == 6 && presentedIds.SequenceEqual([100L, 102L]);
                    var path = Path.GetFullPath(reportPath); Directory.CreateDirectory(Path.GetDirectoryName(path)!);
                    File.WriteAllText(path, JsonSerializer.Serialize(new
                    {
                        Passed = passed, Scope = "Production ConfirmedVideoView; no codec, capture or transport. D3D11 event confirms GPU completion after Present submission; physical scanout is not timed.",
                        DurationSeconds = elapsed.Elapsed.TotalSeconds, ExpectedGpuCounts = new[] { 1, 1, 2, 2 },
                        PresentedFrameIds = presentedIds, Assertions = assertions, Errors = errors
                    }, AppConfiguration.JsonOptions));
                    regressionExitCode = passed ? 0 : 1;
                }
                catch (Exception ex) { Console.Error.WriteLine(ex); regressionExitCode = 1; }
                Close(); cancellation.Dispose();
            }
        }

        async Task AwaitCount(int count)
        {
            var elapsed = System.Diagnostics.Stopwatch.StartNew();
            while (PresentedCount < count)
            {
                if (elapsed.Elapsed > TimeSpan.FromSeconds(3)) throw new TimeoutException($"Expected {count} GPU completions, observed {PresentedCount}.");
                await Task.Delay(10, cancellation.Token);
            }
        }

        void CheckCount(string stage, int expected)
        {
            var actual = PresentedCount;
            assertions.Add(new { Stage = stage, ExpectedGpuCount = expected, ActualGpuCount = actual, Passed = actual == expected });
            if (actual != expected) throw new InvalidOperationException($"{stage}: expected {expected} GPU completions, got {actual}.");
        }

        void CheckAspect(string stage)
        {
            var expected = config.Width / (double)config.Height;
            var actual = view.Bounds.Width / view.Bounds.Height;
            var passed = view.Bounds.Width > 0 && view.Bounds.Height > 0 && Math.Abs(actual - expected) < .005;
            assertions.Add(new { Stage = stage, WindowWidth = Width, WindowHeight = Height, ViewWidth = view.Bounds.Width, ViewHeight = view.Bounds.Height, ExpectedAspect = expected, ActualAspect = actual, Passed = passed });
            if (!passed) throw new InvalidOperationException($"{stage}: rendered view has aspect {actual}, expected {expected}.");
        }
    }
}

// Source: FfmpegUiRegression.cs
static partial class FfmpegUi
{
    sealed partial class DesktopWindow
    {
        async Task VerifyOverlayAsync()
        {
            await Task.Delay(100);
            if (stopping) return;
            if (operation.Text?.StartsWith("已连接：", StringComparison.Ordinal) != true)
                throw new InvalidOperationException("连接成功后控制栏仍显示启动状态。");
            var originalState = WindowState;
            var originalSize = new Size(Width, Height);
            var originalPosition = Position;
            var originalExpanded = details.IsVisible;
            var originalOrbFraction = orbFraction;
            var originalPanelFraction = panelFraction;
            var originalWatermark = showWatermark.IsChecked;
            var originalDiagnostics = packetDiagnostics.IsChecked;
            var originalConfiguration = JsonSerializer.Serialize(session?.Configuration, AppConfiguration.JsonOptions);
            var layouts = new List<object>();
            OverlayBounds? expandedBounds = null, foldedBounds = null;
            var expandedHeight = 0d;
            var foldedHeight = 0d;
            var nativeOwner = false;
            var passThrough = false;
            var keptOrb = false;
            var edgeClamping = false;
            var resizeRetainedOrb = false;
            var panelEdgeClamping = false;
            var resizeRetainedPanel = false;
            var collapseRetainedPanel = false;
            var watermarkHideIndependent = false;
            var watermarkHideSurvivesRestore = false;
            var normalFullScreenRestored = false;
            var maximizedFullScreenRestored = false;
            overlayPassed = false;

            object Report(string? failure = null) => new
            {
                Passed = overlayPassed, Failure = failure,
                WatermarkMouseTransparent = passThrough, WatermarkCannotActivate = passThrough,
                WatermarkOpacity = .8, NativeOwnedWindow = nativeOwner,
                ExpandedHeight = expandedHeight, CollapsedHeight = foldedHeight,
                CollapseButtonRemainsVisible = keptOrb, FloatingOrbRemainsVisible = keptOrb,
                OrbEdgeClamping = edgeClamping, OrbAccessibleAfterResize = resizeRetainedOrb,
                PanelEdgeClamping = panelEdgeClamping, PanelAccessibleAfterResize = resizeRetainedPanel,
                PanelPositionSurvivesCollapse = collapseRetainedPanel,
                WatermarkHideIndependent = watermarkHideIndependent,
                WatermarkHideSurvivesRestore = watermarkHideSurvivesRestore,
                NormalFullScreenRestored = normalFullScreenRestored,
                MaximizedFullScreenRestored = maximizedFullScreenRestored,
                ExpandedBounds = expandedBounds, FoldedBounds = foldedBounds,
                LayoutChecks = layouts
            };

            void Require(bool passed, string message)
            {
                if (!passed) throw new InvalidOperationException("真实控制浮层回归失败：" + message);
            }

            async Task SettleAsync(Func<bool> ready, string message)
            {
                var deadline = DateTime.UtcNow.AddSeconds(2);
                do
                {
                    if (stopping) throw new OperationCanceledException("控制浮层回归期间窗口已关闭。");
                    PositionOverlay();
                    await Task.Delay(200);
                    if (ready()) return;
                }
                while (DateTime.UtcNow < deadline);
                Require(false, message);
            }

            OverlayBounds CheckLayout(string scenario, bool expanded)
            {
                var bounds = CheckOverlayBounds(expanded);
                layouts.Add(new { Scenario = scenario, RequestedWidth = Width, RequestedHeight = Height, ClientSize.Width, ClientSize.Height, Bounds = bounds });
                Require(bounds.Passed, $"{scenario}：浮层、可见控件或悬浮球超出可操作范围。{JsonSerializer.Serialize(bounds)}");
                return bounds;
            }

            bool ConfigurationUnchanged() => packetDiagnostics.IsChecked == originalDiagnostics &&
                JsonSerializer.Serialize(session?.Configuration, AppConfiguration.JsonOptions) == originalConfiguration;

            bool WatermarkVisible() => watermark.IsVisible && IsRegressionWindowVisible(watermark.TryGetPlatformHandle()?.Handle ?? 0);
            bool WatermarkHidden() => !watermark.IsVisible && !IsRegressionWindowVisible(watermark.TryGetPlatformHandle()?.Handle ?? 0);

            bool PanelAtFraction(Point fraction)
            {
                var expected = this.PointToScreen(new Point(
                    ChromeMargin + fraction.X * Math.Max(0, ClientSize.Width - overlay.ClientSize.Width - ChromeMargin * 2),
                    ChromeMargin + fraction.Y * Math.Max(0, ClientSize.Height - overlay.ClientSize.Height - ChromeMargin * 2)));
                var actual = overlay.PointToScreen(new Point());
                return Math.Abs(actual.X - expected.X) <= 2 && Math.Abs(actual.Y - expected.Y) <= 2;
            }

            async Task<bool> CheckFullScreenAsync(WindowState priorState)
            {
                var size = ClientSize;
                var width = Width;
                var height = Height;
                var position = Position;
                ToggleFullScreen();
                await SettleAsync(() => WindowState == WindowState.FullScreen && CheckOverlayBounds(true).Passed,
                    $"{priorState} 状态未进入可操作的全屏布局。");
                CheckLayout($"fullscreen-from-{priorState}", true);
                ToggleFullScreen();
                await SettleAsync(() => WindowState == priorState &&
                    Math.Abs(ClientSize.Width - size.Width) <= 2 && Math.Abs(ClientSize.Height - size.Height) <= 2 &&
                    Math.Abs(Width - width) <= 2 && Math.Abs(Height - height) <= 2 &&
                    Math.Abs(Position.X - position.X) <= 2 && Math.Abs(Position.Y - position.Y) <= 2 && CheckOverlayBounds(true).Passed,
                    $"退出全屏后未还原 {priorState} 的状态、尺寸和位置。");
                CheckLayout($"fullscreen-restored-{priorState}", true);
                return true;
            }

            try
            {
                if (WindowState == WindowState.FullScreen) ToggleFullScreen();
                WindowState = WindowState.Normal;
                if (!details.IsVisible) ToggleDetails();
                showWatermark.IsChecked = true;
                foreach (var size in new[] { new Size(1280, 860), new Size(780, 520), new Size(980, 600), new Size(680, 460) })
                {
                    Width = size.Width; Height = size.Height;
                    await SettleAsync(() => overlay.IsVisible && WatermarkVisible() && CheckOverlayBounds(true).Passed,
                        $"{size.Width}×{size.Height} 展开布局中的控件被裁切。");
                    var bounds = CheckLayout($"expanded-{size.Width}x{size.Height}", true);
                    SaveChromePreview($"controls-{size.Width}");
                    if (expandedHeight == 0) { expandedHeight = bounds.Height; expandedBounds = bounds; }
                }

                var ownerHandle = TryGetPlatformHandle()?.Handle ?? 0;
                var overlayHandle = overlay.TryGetPlatformHandle()?.Handle ?? 0;
                nativeOwner = ownerHandle != 0 && overlayHandle != 0 && GetWindow(overlayHandle, 4) == ownerHandle;
                Require(nativeOwner, "控制栏不是预览窗口的原生从属窗口。");
                passThrough = watermark.VerifyPassThrough(preview.SourceWindow);
                Require(passThrough, "诊断水印必须鼠标穿透且不能激活。");

                Width = 1280; Height = 860;
                await SettleAsync(() => CheckOverlayBounds(true).Passed, "工具栏拖动测试前布局无效。");
                MoveControlPanel(new Point(-100000, -100000));
                await SettleAsync(() => CheckOverlayBounds(true).Passed && PanelAtFraction(new Point()),
                    "工具栏拖至左上方后未限制到窗口内边界。");
                CheckLayout("panel-clamped-top-left", true);
                Require(panelFraction == new Point(), "工具栏左上越界位置未正确限制。");
                MoveControlPanel(new Point(100000, 100000));
                await SettleAsync(() => CheckOverlayBounds(true).Passed && PanelAtFraction(new Point(1, 1)),
                    "工具栏拖至右下方后未限制到窗口内边界。");
                CheckLayout("panel-clamped-bottom-right", true);
                panelEdgeClamping = panelFraction == new Point(1, 1);
                Require(panelEdgeClamping, "工具栏右下越界位置未正确限制。");
                var movedPanelFraction = panelFraction;
                Width = 680; Height = 460;
                await SettleAsync(() => CheckOverlayBounds(true).Passed && PanelAtFraction(movedPanelFraction),
                    "缩小到最小窗口后工具栏无法操作或丢失拖动位置。");
                CheckLayout("panel-after-minimum-resize", true);
                resizeRetainedPanel = panelFraction == movedPanelFraction;
                Require(resizeRetainedPanel, "窗口缩放未保留工具栏位置。");
                Width = 980; Height = 600;
                await SettleAsync(() => CheckOverlayBounds(true).Passed && PanelAtFraction(movedPanelFraction),
                    "重新放大窗口后工具栏丢失拖动位置。");
                CheckLayout("panel-after-grow", true);

                ToggleDetails();
                await SettleAsync(() => CheckOverlayBounds(false).Passed, "收起后未形成独立的 50×50 悬浮球。");
                var folded = CheckLayout("collapsed", false);
                SaveChromePreview("orb");
                foldedHeight = folded.Height; foldedBounds = folded;
                keptOrb = floatingOrb.IsEffectivelyVisible && overlay.IsVisible && !details.IsVisible && !controlPanel.IsVisible;
                Require(keptOrb && foldedHeight < expandedHeight, "收起后仍存在工具栏，或缺少可点击的悬浮球。");

                MoveOrb(new Point(-100000, -100000));
                await SettleAsync(() => CheckOverlayBounds(false).Passed, "悬浮球移至左上方后未限制到窗口内。");
                CheckLayout("orb-clamped-top-left", false);
                Require(orbFraction.X == 0 && orbFraction.Y == 0, "悬浮球左上越界位置未正确限制。");
                MoveOrb(new Point(100000, 100000));
                await SettleAsync(() => CheckOverlayBounds(false).Passed, "悬浮球移至右下方后未限制到窗口内。");
                CheckLayout("orb-clamped-bottom-right", false);
                edgeClamping = orbFraction.X == 1 && orbFraction.Y == 1;
                Require(edgeClamping, "悬浮球右下越界位置未正确限制。");
                var movedFraction = orbFraction;
                Width = 680; Height = 460;
                await SettleAsync(() => CheckOverlayBounds(false).Passed, "缩小窗口后悬浮球无法操作。");
                CheckLayout("orb-after-resize", false);
                resizeRetainedOrb = orbFraction == movedFraction && floatingOrb.IsEffectivelyVisible;
                Require(resizeRetainedOrb, "窗口缩放未保留悬浮球位置。");
                ToggleDetails();
                await SettleAsync(() => CheckOverlayBounds(true).Passed && PanelAtFraction(movedPanelFraction),
                    "悬浮球展开后控件被裁切或工具栏丢失拖动位置。");
                CheckLayout("expanded-after-orb-move", true);
                collapseRetainedPanel = panelFraction == movedPanelFraction;
                Require(collapseRetainedPanel, "收起、移动悬浮球并展开后工具栏未保留拖动位置。");

                showWatermark.IsChecked = false;
                await SettleAsync(() => WatermarkHidden(), "关闭诊断水印后窗口仍可见。");
                watermarkHideIndependent = ConfigurationUnchanged();
                Require(watermarkHideIndependent, "隐藏水印改变了诊断包开关或会话配置。");
                WindowState = WindowState.Minimized;
                await SettleAsync(() => WindowState == WindowState.Minimized, "窗口无法最小化。");
                WindowState = WindowState.Normal;
                await SettleAsync(() => WindowState == WindowState.Normal && overlay.IsVisible && CheckOverlayBounds(true).Passed,
                    "最小化恢复后控制浮层未恢复。");
                watermarkHideSurvivesRestore = showWatermark.IsChecked == false && WatermarkHidden() && ConfigurationUnchanged();
                Require(watermarkHideSurvivesRestore, "最小化恢复后已隐藏的水印重新显示，或改变了会话配置。");
                showWatermark.IsChecked = true;
                await SettleAsync(() => WatermarkVisible(), "诊断水印无法重新显示。");
                Require(watermark.VerifyPassThrough(preview.SourceWindow), "重新显示后水印不再鼠标穿透。");

                Width = 980; Height = 600;
                await SettleAsync(() => CheckOverlayBounds(true).Passed, "全屏测试前控制浮层布局无效。");
                normalFullScreenRestored = await CheckFullScreenAsync(WindowState.Normal);
                WindowState = WindowState.Maximized;
                await SettleAsync(() => WindowState == WindowState.Maximized && CheckOverlayBounds(true).Passed,
                    "窗口无法最大化。");
                maximizedFullScreenRestored = await CheckFullScreenAsync(WindowState.Maximized);
                Require(ConfigurationUnchanged(), "显示操作改变了诊断包开关或会话配置。");
                overlayPassed = true;
                overlayCheck = Report();
            }
            catch (Exception error)
            {
                overlayCheck = Report(error.Message);
                throw;
            }
            finally
            {
                if (!stopping)
                {
                    if (WindowState == WindowState.FullScreen) { ToggleFullScreen(); await Task.Delay(200); }
                    WindowState = WindowState.Normal;
                    Width = originalSize.Width; Height = originalSize.Height; Position = originalPosition;
                    orbFraction = originalOrbFraction;
                    panelFraction = originalPanelFraction;
                    if (details.IsVisible != originalExpanded) ToggleDetails();
                    showWatermark.IsChecked = originalWatermark;
                    WindowState = originalState;
                    PositionOverlay();
                    await Task.Delay(100);
                    PositionOverlay();
                }
            }
        }

        sealed record OverlayBounds(bool Passed, bool InsidePreview, bool ControlsInsideOverlay, double Width, double Height,
            bool ControlsVisible, bool CorrectPresentation, bool ControlsDoNotOverlap);

        void SaveChromePreview(string name)
        {
            if (reportPath == null) return;
            var directory = Path.GetDirectoryName(Path.GetFullPath(reportPath))!;
            Directory.CreateDirectory(directory);
            using var bitmap = new Avalonia.Media.Imaging.RenderTargetBitmap(
                new PixelSize((int)Math.Ceiling(overlay.ClientSize.Width * overlay.RenderScaling),
                    (int)Math.Ceiling(overlay.ClientSize.Height * overlay.RenderScaling)),
                new Vector(96 * overlay.RenderScaling, 96 * overlay.RenderScaling));
            bitmap.Render(chromeRoot);
            bitmap.Save(Path.Combine(directory, name + ".png"), Avalonia.Media.Imaging.PngBitmapEncoderOptions.Default);
        }

        [DllImport("user32.dll", EntryPoint = "IsWindowVisible")]
        [return: MarshalAs(UnmanagedType.Bool)]
        static extern bool IsRegressionWindowVisible(nint window);

        OverlayBounds CheckOverlayBounds(bool expanded)
        {
            var origin = overlay.PointToScreen(new Point());
            var outerOrigin = this.PointToScreen(new Point());
            var width = overlay.ClientSize.Width * overlay.RenderScaling;
            var height = overlay.ClientSize.Height * overlay.RenderScaling;
            var inside = overlay.IsVisible && origin.X >= outerOrigin.X - 1 && origin.Y >= outerOrigin.Y - 1 &&
                origin.X + width <= outerOrigin.X + ClientSize.Width * RenderScaling + 1 &&
                origin.Y + height <= outerOrigin.Y + ClientSize.Height * RenderScaling + 1;
            Control[] expandedControls = [controlTitle, inputEnabled, packetDiagnostics, collapse, presets, bitrate, bitrateLabel,
                clipboardEnabled, fullScreen, showWatermark];
            Control[] controls = expanded ? expandedControls : [floatingOrb];
            var visible = controls.All(control => control.IsEffectivelyVisible && control.Bounds.Width > 0 && control.Bounds.Height > 0);
            var rectangles = controls.Select(control =>
            {
                var point = control.PointToScreen(new Point());
                return new Rect(point.X, point.Y, control.Bounds.Width * overlay.RenderScaling, control.Bounds.Height * overlay.RenderScaling);
            }).ToArray();
            var contentInside = rectangles.All(rect => rect.Left >= origin.X - 1 && rect.Top >= origin.Y - 1 &&
                rect.Right <= origin.X + width + 1 && rect.Bottom <= origin.Y + height + 1);
            var noOverlap = !rectangles.Where((rect, index) => rectangles.Skip(index + 1).Any(other =>
                Math.Min(rect.Right, other.Right) - Math.Max(rect.Left, other.Left) > 1 &&
                Math.Min(rect.Bottom, other.Bottom) - Math.Max(rect.Top, other.Top) > 1)).Any();
            var presentation = expanded
                ? details.IsVisible && controlPanel.IsVisible && !floatingOrb.IsVisible && overlay.ClientSize.Width <= Math.Min(980, ClientSize.Width - 24) + 1
                : !details.IsVisible && !controlPanel.IsVisible && floatingOrb.IsHitTestVisible &&
                    expandedControls.All(control => !control.IsEffectivelyVisible) &&
                    Math.Abs(overlay.ClientSize.Width - OrbSize) <= 1 && Math.Abs(overlay.ClientSize.Height - OrbSize) <= 1;
            return new(inside && contentInside && visible && presentation && noOverlap, inside, contentInside,
                overlay.ClientSize.Width, overlay.ClientSize.Height, visible, presentation, noOverlap);
        }
    }
}

// Source: FfmpegWatermark.cs
sealed class DiagnosticWatermark : Window
{
    const int ExtendedStyle = -20, NoActivate = 0x08000000;
    readonly SubclassProcedure procedure;
    nint handle;

    public DiagnosticWatermark()
    {
        procedure = WindowProcedure;
        Title = "FRD 诊断水印";
        WindowDecorations = WindowDecorations.None;
        CanResize = false; ShowInTaskbar = false; ShowActivated = false;
        Focusable = false; IsHitTestVisible = false;
        SizeToContent = SizeToContent.Height;
        Background = Brushes.Transparent;
        TransparencyLevelHint = [WindowTransparencyLevel.Transparent];
        RequestedThemeVariant = Avalonia.Styling.ThemeVariant.Dark;
    }

    protected override void OnOpened(EventArgs e)
    {
        handle = TryGetPlatformHandle()?.Handle ?? throw new InvalidOperationException("Missing diagnostic watermark HWND.");
        var style = GetWindowLong(handle, ExtendedStyle);
        Marshal.SetLastPInvokeError(0);
        if (SetWindowLong(handle, ExtendedStyle, style | NoActivate) == 0 && Marshal.GetLastWin32Error() != 0)
            throw new Win32Exception(Marshal.GetLastWin32Error(), "Cannot disable watermark activation.");
        if (!SetWindowSubclass(handle, procedure, 1, 0))
            throw new Win32Exception(Marshal.GetLastWin32Error(), "Cannot make diagnostics click-through.");
        base.OnOpened(e);
    }

    nint WindowProcedure(nint hwnd, uint message, nuint wParam, nint lParam, nuint id, nuint reference)
    {
        // Both windows belong to the UI thread; HTTRANSPARENT continues hit testing beneath this HWND.
        if (message == 0x0084) return -1;
        if (message == 0x0021) return 3;
        if (message == 0x0082 && !RemoveWindowSubclass(hwnd, procedure, id))
            Console.Error.WriteLine("[watermark] Cannot detach native hit-test handler: " + Marshal.GetLastWin32Error());
        return DefSubclassProc(hwnd, message, wParam, lParam);
    }

    public bool VerifyPassThrough(nint preview)
    {
        var origin = this.PointToScreen(new Point(8, 8));
        var position = (nint)((origin.X & 0xffff) | ((origin.Y & 0xffff) << 16));
        return handle != 0 && preview != 0 && !Focusable && !IsHitTestVisible &&
            (GetWindowLong(handle, ExtendedStyle) & NoActivate) != 0 &&
            GetWindowThreadProcessId(handle, out _) == GetWindowThreadProcessId(preview, out _) &&
            SendMessage(handle, 0x0084, 0, position) == -1 && SendMessage(handle, 0x0021, 0, 0) == 3;
    }

    delegate nint SubclassProcedure(nint hwnd, uint message, nuint wParam, nint lParam, nuint id, nuint reference);
    [DllImport("user32.dll", EntryPoint = "GetWindowLongW")] static extern int GetWindowLong(nint hwnd, int index);
    [DllImport("user32.dll", EntryPoint = "SetWindowLongW", SetLastError = true)] static extern int SetWindowLong(nint hwnd, int index, int value);
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(nint hwnd, out uint process);
    [DllImport("user32.dll", EntryPoint = "SendMessageW")] static extern nint SendMessage(nint hwnd, uint message, nuint wParam, nint lParam);
    [DllImport("comctl32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)] static extern bool SetWindowSubclass(nint hwnd, SubclassProcedure callback, nuint id, nuint reference);
    [DllImport("comctl32.dll", SetLastError = true)] [return: MarshalAs(UnmanagedType.Bool)] static extern bool RemoveWindowSubclass(nint hwnd, SubclassProcedure callback, nuint id);
    [DllImport("comctl32.dll")] static extern nint DefSubclassProc(nint hwnd, uint message, nuint wParam, nint lParam);
}
